@media (max-width: 768px) {
  .mediaCards {
    grid-template-columns: 1fr;
  }

  .drawer,
  .modal {
    width: 95%;
  }

  .drawerContent,
  .modalContent {
    padding: 20px;
  }

  .modalFooter,
  .drawerActions {
    flex-direction: column;
  }

  .cancelButton,
  .submitButton {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .sectionTitle {
    font-size: 24px;
  }

  .drawerTitle,
  .modalTitle {
    font-size: 20px;
  }
}

