  margin-bottom: 10px;
  color: #333;
}

.textarea {
  width: 100%;
  padding: 12px 15px;
  border: 1px solid #ddd;
  border-radius: 8px;
  font-size: 16px;
  color: #333;
  background-color: #f9f9f9;
  transition: all 0.3s ease;
  resize: vertical;
}

.textarea:focus {
  border-color: #4776e6;
  outline: none;
  box-shadow: 0 0 0 3px rgba(71, 118, 230, 0.1);
}

/* Action buttons */
.drawerActions {
  display: flex;
  justify-content: flex-end;
  gap: 15px;
  margin-top: 30px;
}

.cancelButton,
.submitButton {
  padding: 12px 25px;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s ease;
  border: none;
}

.cancelButton {
  background-color: #f0f0f0;
  color: #666;
}

.submitButton {
  background: linear-gradient(135deg, #4776e6, #8e54e9);
  color: white;
  box-shadow: 0 4px 10px rgba(71, 118, 230, 0.2);
}

.cancelButton:hover {
  background-color: #e0e0e0;
}

.submitButton:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 15px rgba(71, 118, 230, 0.3);
}

.submitButton:disabled {
  background: linear-gradient(135deg, #c5c5c5, #a5a5a5);
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

/* Modal styles */
.modalOverlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  animation: fadeIn 0.3s ease;
}

.modal {
  background-color: #fff;
  border-radius: 16px;
  width: 90%;
  max-width: 800px;
  max-height: 90vh;
  overflow-y: auto;
  position: relative;
  animation: slideIn 0.3s ease;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
  display: flex;
  flex-direction: column;
}

.modalHeader {
  padding: 20px 25px;
  border-bottom: 1px solid #eee;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modalTitle {
  font-size: 24px;
  font-weight: 700;
  color: #333;
  margin: 0;
}

.modalClose {
  background: none;
  border: none;
  font-size: 28px;
  cursor: pointer;
  color: #999;
  transition: color 0.3s ease;
}

.modalClose:hover {
  color: #333;
}

.modalContent {
  padding: 25px;
  flex-grow: 1;
}

.modalFooter {
  padding: 20px 25px;
  border-top: 1px solid #eee;
  display: flex;
  justify-content: flex-end;
  gap: 15px;
}

.editorSection {
  margin-bottom: 30px;
}

.editorSection label {
  display: block;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 10px;
  color: #333;
}

.categoriesSection {
  margin-bottom: 25px;
}

.categoriesSection label {
  display: block;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 10px;
  color: #333;
}

/* Responsive styles */
@media (max-width: 768px) {
  .mediaCards {
    grid-template-columns: 1fr;
  }

  .drawer,
  .modal {
    width: 95%;
  }

  .drawerContent,
  .modalContent {
    padding: 20px;
  }

  .modalFooter,
  .drawerActions {
    flex-direction: column;
  }

  .cancelButton,
  .submitButton {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .sectionTitle {
    font-size: 24px;
  }

  .drawerTitle,
  .modalTitle {
    font-size: 20px;
  }
}
